import { page, userEvent } from '../helpers/locator'
import { afterEach, beforeEach, describe, expect, it } from 'vitest'
import { expectElement, expectPoll } from '../helpers/assertions'
import { createTestApp } from '../helpers/createTestApp'
import { cleanupIntegrationTest, setupIntegrationTest } from '../helpers/integrationSetup'


describe('Timed Block Workflows', () => {
  beforeEach(setupIntegrationTest)
  afterEach(cleanupIntegrationTest)

  describe('Configuration', () => {
    it('allows user to add timed blocks from the dialog and start workout', async () => {
      const { builder, common, cleanup } =
        await createTestApp()

      await builder.navigateTo()
      await builder.openAddBlockDialog()

      // Verify exercises tab is default (check aria-selected attribute)
      await expectElement(page.getByRole('tab', { name: /exercises/i })).toHaveAttribute('aria-selected', 'true')

      // Switch to timed blocks tab
      await builder.switchToTimedBlocksTab()

      // Verify all block types are available
      await expectElement(page.getByText('AMRAP')).toBeInTheDocument()
      await expectElement(page.getByText('EMOM')).toBeInTheDocument()
      await expectElement(page.getByText('Tabata')).toBeInTheDocument()
      await expectElement(page.getByText('For Time')).toBeInTheDocument()

      // Select AMRAP - this opens a configuration dialog
      await userEvent.click(common.getDialogButton('AMRAP'))

      // Wait for configuration dialog
      await expectElement(page.getByRole('dialog')).toBeVisible()
      await expectElement(page.getByText(/Configure/)).toBeVisible()

      // Add an exercise to the AMRAP
      await userEvent.click(common.getDialogButton('Add Exercise'))
      await common.selectExercise('Push-ups')

      // Confirm the block by clicking "Add Block"
      await userEvent.click(common.getDialogButton('Add Block'))

      // Wait for dialog AND overlay to fully close
      await common.waitForDialogClose()

      // Verify AMRAP block appears in builder
      const playlistButtons = await builder.getPlaylistBlockButtons()
      expect(playlistButtons.length).toBe(1)

      // Start workout and verify timer UI
      await builder.startWorkout()

      // Wait for active mode
      await expectElement(page.getByText(/block 1 of 1/i)).toBeVisible()

      // Timer should display (verify Start button appears)
      await expectElement(page.getByRole('button', { name: /start/i })).toBeInTheDocument()

      cleanup()
    })

    it('filters exercises when searching in add block dialog', async () => {
      const { builder, common, cleanup } =
        await createTestApp()

      await builder.navigateTo()
      await builder.openAddBlockDialog()

      // Multiple exercises should be visible initially (at top of alphabetical list)
      await expectElement(page.getByText('Assisted Pull-up Machine')).toBeInTheDocument()
      await expectElement(page.getByText('Barbell Row')).toBeInTheDocument()

      // Type in search input to filter
      await page.getByRole('textbox').fill('barbell row')

      // Only matching exercise should remain
      await expectElement(page.getByText('Barbell Row')).toBeVisible()
      await expectElement(page.getByText('Assisted Pull-up Machine')).not.toBeInTheDocument()

      // Select the filtered exercise and verify it adds to workout
      await userEvent.click(common.getDialogButton('Barbell Row'))

      // Wait for dialog AND overlay to fully close
      await common.waitForDialogClose()

      // Verify exercise was added to builder
      const playlistButtons = await builder.getPlaylistBlockButtons()
      expect(playlistButtons.length).toBe(1)

      cleanup()
    })
  })

  describe('Execution', () => {
    it('creates AMRAP block and shows timer UI', async () => {
      const { builder, workout, router, cleanup } = await createTestApp()

      await builder.navigateTo()
      await builder.addTimedBlock('AMRAP')
      await builder.startWorkoutAndVerifyBlocks(1)

      // Verify AMRAP view is shown with Start button
      await expectElement(page.getByRole('heading', { name: /amrap/i })).toBeInTheDocument()
      await expectElement(page.getByRole('button', { name: /start/i })).toBeInTheDocument()
      await expectElement(page.getByText(/rounds/i)).toBeInTheDocument()
      await expectElement(page.getByRole('button', { name: /\+1/i })).toBeInTheDocument()

      await workout.endWorkoutAndNavigateToSummary()
      expect(router.currentRoute.value.path).toMatch(/^\/workout\/summary\//)

      cleanup()
    })

    it('creates EMOM block and shows minute display', async () => {
      const { builder, cleanup } = await createTestApp()

      await builder.navigateTo()
      await builder.addTimedBlock('EMOM')
      await builder.startWorkoutAndVerifyBlocks(1)

      // Verify EMOM view shows minute counter and exercise
      await expectElement(page.getByText(/min/i)).toBeVisible()
      await expectElement(page.getByRole('button', { name: /start/i })).toBeVisible()
      await expectElement(page.getByText('Push-ups')).toBeVisible()

      cleanup()
    })

    it('creates Tabata block and shows round/phase info', async () => {
      const { builder, cleanup } = await createTestApp()

      await builder.navigateTo()
      await builder.addTimedBlock('Tabata')
      await builder.startWorkoutAndVerifyBlocks(1)

      // Verify Tabata view shows phase badge and start button
      await expectElement(page.getByText('WORK', { exact: true })).toBeInTheDocument()
      await expectElement(page.getByRole('button', { name: /start/i })).toBeInTheDocument()

      cleanup()
    })

    it('creates For Time block and completes with Done button', async () => {
      const { builder, common, router, cleanup } = await createTestApp()

      await builder.navigateTo()
      await builder.addTimedBlock('For Time')
      await builder.startWorkoutAndVerifyBlocks(1)

      // Verify For Time view is shown with Done button (not Start/Pause)
      await expectElement(page.getByRole('heading', { name: /for time/i })).toBeInTheDocument()
      const doneButton = page.getByRole('button', { name: /done/i })
      await expectElement(doneButton).toBeInTheDocument()

      // Click Done - this directly opens the finish workout dialog (unlike other blocks)
      await doneButton.click()
      await common.waitForDialog()
      await userEvent.click(common.getDialogButton('Finish Workout'))

      // Wait for completion screen and navigate to summary
      await expectElement(page.getByText(/workout complete/i)).toBeVisible()
      const viewDetailsButton = page.getByRole('button', { name: /view details/i })
      await expectElement(viewDetailsButton, { timeout: 2000 }).toBeVisible()
      await expectPoll(async () => {
        const element = await viewDetailsButton.element()
        return getComputedStyle(element).opacity
      }, { timeout: 2000 }).toBe('1')
      await viewDetailsButton.click()

      await common.waitForRoute(/^\/workout\/summary\//)
      expect(router.currentRoute.value.path).toMatch(/^\/workout\/summary\//)

      cleanup()
    })

    it('navigates between strength and timed blocks in hybrid workout', async () => {
      const { builder, workout, common, cleanup } = await createTestApp()

      // Add strength block first, then AMRAP block
      await builder.navigateTo()
      await builder.openAddBlockDialog()
      // Search for exact exercise to avoid ambiguous matches with Smith Machine Bench Press
      await userEvent.fill(page.getByRole('textbox'), 'Bench Press')
      await userEvent.click(common.getDialogButton('Bench Press'))
      await common.waitForDialogClose()
      await builder.addTimedBlock('AMRAP')
      await builder.startWorkoutAndVerifyBlocks(2)

      // Verify strength view shows Complete Set button
      await expectElement(page.getByRole('button', { name: /complete set/i })).toBeInTheDocument()

      // Navigate to AMRAP block
      await userEvent.click(await workout.getFooterButton('next'))
      await expectElement(page.getByText(/block 2 of 2/i)).toBeVisible()
      await expectElement(page.getByRole('button', { name: /start/i })).toBeInTheDocument()

      // Navigate back to strength block
      await userEvent.click(await workout.getFooterButton('prev'))
      await expectElement(page.getByText(/block 1 of 2/i)).toBeVisible()
      await expectElement(page.getByRole('button', { name: /complete set/i })).toBeInTheDocument()

      cleanup()
    })

    it('AMRAP block allows incrementing rounds with +1 button', async () => {
      const { builder, workout, router, cleanup } = await createTestApp()

      await builder.navigateTo()
      await builder.addTimedBlock('AMRAP')
      await builder.startWorkoutAndVerifyBlocks(1)

      // Verify AMRAP UI elements
      await expectElement(page.getByRole('heading', { name: /amrap/i })).toBeInTheDocument()
      await expectElement(page.getByRole('button', { name: /start/i })).toBeInTheDocument()
      await expectElement(page.getByText(/rounds/i)).toBeInTheDocument()

      // Start the timer
      await page.getByRole('button', { name: /start/i }).click()

      // Wait for +1 button to be enabled (timer must be running)
      await expectPoll(async () => {
        const plusButton = await page.getByRole('button', { name: /\+1/i }).element()
        return plusButton instanceof HTMLButtonElement && !plusButton.disabled
      }).toBe(true)

      // Increment rounds
      await page.getByRole('button', { name: /\+1/i }).click()
      await page.getByRole('button', { name: /\+1/i }).click()

      await workout.endWorkoutAndNavigateToSummary()
      expect(router.currentRoute.value.path).toMatch(/^\/workout\/summary\//)

      cleanup()
    })

    it('timer button changes to Pause when running', async () => {
      const { builder, cleanup } = await createTestApp()

      await builder.navigateTo()
      await builder.addTimedBlock('EMOM')
      await builder.startWorkoutAndVerifyBlocks(1)

      // Verify Start button exists (not Pause)
      await expectElement(page.getByRole('button', { name: /start/i })).toBeInTheDocument()
      await expectElement(page.getByRole('button', { name: /pause/i })).not.toBeInTheDocument()

      // Click Start
      await page.getByRole('button', { name: /start/i }).click()

      // Verify button changed to Pause
      await expectElement(page.getByRole('button', { name: /pause/i })).toBeVisible()
      await expectElement(page.getByRole('button', { name: /start/i })).not.toBeInTheDocument()

      cleanup()
    })
  })

  describe('Complete Journeys', () => {
    it('completes AMRAP workout with rounds recorded', async () => {
      const { builder, workout, router, cleanup } = await createTestApp()

      await builder.navigateTo()
      await builder.addTimedBlock('AMRAP')
      await builder.startWorkoutAndVerifyBlocks(1)

      // Verify AMRAP UI shows
      await expectElement(page.getByRole('heading', { name: /amrap/i })).toBeInTheDocument()
      await expectElement(page.getByText(/rounds/i)).toBeInTheDocument()

      // Start the timer
      await page.getByRole('button', { name: /start/i }).click()

      // Wait for +1 button to be enabled (timer must be running)
      await expectPoll(async () => {
        const plusButton = await page.getByRole('button', { name: /\+1/i }).element()
        return plusButton instanceof HTMLButtonElement && !plusButton.disabled
      }).toBe(true)

      // Click +1 to record 3 rounds
      await page.getByRole('button', { name: /\+1/i }).click()
      await page.getByRole('button', { name: /\+1/i }).click()
      await page.getByRole('button', { name: /\+1/i }).click()

      await expectElement(page.getByText('3')).toBeVisible()

      await workout.endWorkoutAndNavigateToSummary()
      expect(router.currentRoute.value.path).toMatch(/^\/workout\/summary\//)
      await expectElement(page.getByRole('heading', { name: /workout complete/i })).toBeVisible()

      cleanup()
    })

    it('runs EMOM workout and completes full journey', async () => {
      const { builder, workout, router, cleanup } = await createTestApp()

      await builder.navigateTo()
      await builder.addTimedBlock('EMOM')
      await builder.startWorkoutAndVerifyBlocks(1)

      // Verify EMOM view shows minute counter and exercise
      await expectElement(page.getByText(/min/i)).toBeInTheDocument()
      await expectElement(page.getByText('Push-ups')).toBeInTheDocument()
      await expectElement(page.getByRole('button', { name: /start/i })).toBeInTheDocument()

      await workout.endWorkoutAndNavigateToSummary()
      expect(router.currentRoute.value.path).toMatch(/^\/workout\/summary\//)
      await expectElement(page.getByRole('heading', { name: /workout complete/i })).toBeVisible()

      cleanup()
    })
  })
})

import { expect } from 'vitest'
import { page, userEvent } from '../locator'
import { expectElement } from '../assertions'
import type { CommonPO } from './CommonPO'
import { ensureHTMLElement } from '../domHelpers'

/**
 * Page Object for the workout builder view.
 * Provides methods to navigate, add exercise blocks, and start workouts.
 */
export class BuilderPO {
  constructor(private common: CommonPO) {}

  /**
   * Clicks the "Start New Workout" button on the home page.
   * Alias for navigateTo() with clearer intent.
   */
  async clickStartNewWorkout(): Promise<void> {
    await page.getByRole('button', { name: /start new workout/i }).click()
  }

  /**
   * Navigates to the workout builder by clicking the "Start New Workout" card.
   */
  async navigateTo(): Promise<void> {
    await this.clickStartNewWorkout()
  }

  /**
   * Opens the add block dialog by clicking the appropriate button.
   * Handles both empty state ("Add first block") and populated state ("Add block").
   */
  async openAddBlockDialog(): Promise<void> {
    // Use Locator.click() for consistent behavior in both Happy-DOM and browser mode
    const addFirstBlockLocator = page.getByRole('button', { name: /add first block/i })

    // Check which button exists and click it using Locator.click()
    if (addFirstBlockLocator.query()) {
      await addFirstBlockLocator.click()
      await this.common.waitForDialog()
      return
    }

    await page.getByRole('button', { name: /add block/i }).click()
    await this.common.waitForDialog()
  }

  /**
   * Adds a strength exercise block to the workout.
   * Navigates to builder, opens dialog, and selects the specified exercise.
   * @param exerciseName - The name of the exercise to add
   */
  async addStrengthBlock(exerciseName: string): Promise<void> {
    await this.navigateTo()
    await this.openAddBlockDialog()
    await userEvent.click(this.common.getDialogButton(exerciseName))
    await this.common.waitForDialogClose()
  }

  /**
   * Starts the workout by clicking the "Start Workout" button.
   */
  async startWorkout(): Promise<void> {
    await page.getByRole('button', { name: /start workout/i }).click()
  }

  /**
   * Verifies the expected number of blocks in the playlist and starts the workout.
   * Waits for the active mode indicator showing current block position.
   * @param expectedBlockCount - The number of blocks expected in the playlist
   */
  async startWorkoutAndVerifyBlocks(expectedBlockCount: number): Promise<void> {
    const playlistButtons = await this.getPlaylistBlockButtons()
    expect(playlistButtons.length).toBe(expectedBlockCount)
    await this.startWorkout()
    await expectElement(page.getByText(new RegExp(`block 1 of ${expectedBlockCount}`, 'i'))).toBeVisible()
  }

  /**
   * Sets up a workout with one or more strength exercises and starts it.
   * Combines navigation, adding blocks, and starting the workout in one call.
   * @param exercises - Array of exercise names to add as blocks
   */
  async setupStrengthWorkoutAndStart(exercises: Array<string>): Promise<void> {
    await this.navigateTo()
    for (const exercise of exercises) {
      await this.openAddBlockDialog()
      await userEvent.click(this.common.getDialogButton(exercise))
      await this.common.waitForDialogClose()
    }
    await this.startWorkout()
    await expectElement(page.getByRole('table')).toBeVisible()
  }

  /**
   * Switches to the timed blocks tab in the add block dialog.
   */
  async switchToTimedBlocksTab(): Promise<void> {
    await page.getByRole('tab', { name: /timed blocks/i }).click()
  }

  /**
   * Retrieves all exercise buttons in the carousel, excluding the "Add exercise" button.
   * @returns Array of toggle button elements representing exercises
   */
  async getCarouselExerciseButtons(): Promise<ReadonlyArray<HTMLElement>> {
    const allButtons = await page.getByRole('button').all()
    const htmlButtons: Array<HTMLElement> = []
    for (const locator of allButtons) {
      const element = ensureHTMLElement(await locator.element())
      if (
        element.getAttribute('aria-pressed') !== null &&
        element.getAttribute('aria-label') !== 'Add exercise'
      ) {
        htmlButtons.push(element)
      }
    }
    return htmlButtons
  }

  /**
   * Retrieves all block buttons in the workout playlist.
   * @returns Array of toggle button elements representing workout blocks
   */
  async getPlaylistBlockButtons(): Promise<ReadonlyArray<HTMLElement>> {
    const allButtons = await page.getByRole('button').all()
    const htmlButtons: Array<HTMLElement> = []
    for (const locator of allButtons) {
      const element = ensureHTMLElement(await locator.element())
      if (element.getAttribute('aria-pressed') !== null) {
        htmlButtons.push(element)
      }
    }
    return htmlButtons
  }

  /**
   * Adds a timed block (AMRAP, EMOM, Tabata, or For Time) with an exercise.
   * Opens the add block dialog, switches to timed blocks tab, configures the block,
   * adds an exercise, and confirms.
   * @param blockType - The type of timed block to add
   * @param exerciseName - The name of the exercise to add (defaults to 'Push-ups')
   */
  async addTimedBlock(
    blockType: 'AMRAP' | 'EMOM' | 'Tabata' | 'For Time',
    exerciseName = 'Push-ups',
  ): Promise<void> {
    await this.openAddBlockDialog()
    await this.switchToTimedBlocksTab()
    // Wait for block type buttons to be visible after tab switch
    await expectElement(page.getByText(blockType, { exact: true })).toBeVisible()
    await userEvent.click(this.common.getDialogButton(blockType))

    // Wait for configure dialog
    await expectElement(page.getByText('Configure')).toBeVisible()

    // Add exercise - Tabata uses "Select Exercise", others use "Add Exercise"
    const exerciseButtonText = blockType === 'Tabata' ? 'Select Exercise' : 'Add Exercise'
    await userEvent.click(this.common.getDialogButton(exerciseButtonText))
    await this.common.selectExercise(exerciseName)

    // Confirm block
    await userEvent.click(this.common.getDialogButton('Add Block'))
    await this.common.waitForDialogClose()
  }

  /**
   * Adds a cardio block to the workout.
   * Opens the add block dialog, switches to timed blocks tab, configures cardio,
   * and confirms.
   * @param activity - The cardio activity to select (defaults to 'Running')
   */
  async addCardioBlock(activity = 'Running'): Promise<void> {
    await this.openAddBlockDialog()
    await this.switchToTimedBlocksTab()
    await userEvent.click(this.common.getDialogButton('Cardio'))

    // Wait for configure dialog
    await expectElement(page.getByText('Configure')).toBeVisible()

    // Select activity by clicking the button with matching text
    await page.getByRole('button', { name: new RegExp(activity, 'i') }).click()

    // Duration defaults to 30 minutes, just confirm
    await userEvent.click(this.common.getDialogButton('Add Block'))
    await this.common.waitForDialogClose()
  }
}

import { flushPromises } from '@vue/test-utils'
import { page, userEvent } from '../locator'
import { expectElement, expectPoll } from '../assertions'
import type { TestContext } from '../types'

/**
 * Base Page Object providing common UI interaction methods shared across all page objects.
 * Handles dialogs, routing, and exercise selection patterns used throughout integration tests.
 */
export class CommonPO {
  constructor(protected context: TestContext) {}

  /**
   * Waits for a dialog element to appear in the DOM.
   */
  async waitForDialog(): Promise<void> {
    await expectElement(page.getByRole('dialog')).toBeVisible()
  }

  /**
   * Waits for a dialog to fully close, including overlay and animations.
   * In browser mode, dialogs use CSS animations that can block pointer events.
   * This method waits for both the dialog element AND overlay to be removed.
   */
  async waitForDialogClose(): Promise<void> {
    await expectElement(page.getByRole('dialog')).not.toBeInTheDocument()
    // eslint-disable-next-line no-restricted-syntax -- Checking overlay data attribute, no accessible equivalent
    await expectPoll(() => document.querySelector('[data-slot="dialog-overlay"]')).toBeNull()
    // Flush any pending Vue updates after dialog unmount
    await flushPromises()
  }

  /**
   * Finds a button inside the currently open dialog by its text content.
   * @param text - The text to search for within button content
   * @returns The matching button element
   * @throws Error if no button with the specified text exists in the dialog
   */
  getDialogButton(text: string): HTMLElement {
    const dialog = page.getByRole('dialog').query()
    if (!dialog) {
      throw new Error('No dialog found')
    }
    // eslint-disable-next-line no-restricted-syntax -- Scoped search within dialog element
    const buttons = dialog.querySelectorAll('button')
    const button = [...buttons].find((b) => b.textContent?.includes(text))

    if (!button) {
      throw new Error(`Dialog button with text "${text}" not found`)
    }
    return button
  }

  /**
   * Checks whether a dialog is currently open.
   * @returns true if a dialog element exists in the DOM
   */
  isDialogOpen(): boolean {
    return page.getByRole('dialog').query() !== null
  }

  /**
   * Searches for and selects an exercise from the exercise picker dialog.
   * Types the exercise name into the search input and clicks the matching result.
   * @param exerciseName - The name of the exercise to search for and select
   */
  async selectExercise(exerciseName: string): Promise<void> {
    const searchInput = page.getByRole('textbox')
    await searchInput.fill(exerciseName)
    await expectPoll(() => this.getExactDialogButton(exerciseName)).toBeTruthy()
    await userEvent.click(this.getExactDialogButton(exerciseName))
  }

  /**
   * Finds a button inside the currently open dialog by exact text match.
   * Uses a more precise matching strategy than getDialogButton to avoid partial matches.
   * For exercise selection, handles two presentation modes:
   * - Dialog mode: <button><span>icon</span><div><p>name</p>...</div></button>
   * - Overlay mode: <button><span>icon</span><span class="font-medium">name</span></button>
   * @param text - The exact text to match
   * @returns The matching button element
   * @throws Error if no button with the exact text exists in the dialog
   */
  private getExactDialogButton(text: string): HTMLElement {
    const dialog = page.getByRole('dialog').query()
    // eslint-disable-next-line no-restricted-syntax -- Finding overlay by CSS classes, no accessible equivalent
    const overlay = document.querySelector('[class*="absolute"][class*="inset-0"]')
    const container = dialog ?? overlay

    if (!container) {
      throw new Error('No dialog or overlay found')
    }

    // eslint-disable-next-line no-restricted-syntax -- Scoped search within container element
    const buttons = container.querySelectorAll('button')

    // First try: exact match of full button text (for simple buttons like "Add Block", "Confirm")
    let button = [...buttons].find((b) => b.textContent?.trim() === text)

    // Second try: find button containing a <p> tag with exact exercise name (dialog mode)
    if (!button) {
      button = [...buttons].find((b) => {
        // eslint-disable-next-line no-restricted-syntax -- DOM traversal within button element
        const paragraphs = b.querySelectorAll('p')
        return [...paragraphs].some((p) => p.textContent?.trim() === text)
      })
    }

    // Third try: find button containing a <span> with class "font-medium" (overlay mode)
    if (!button) {
      button = [...buttons].find((b) => {
        // eslint-disable-next-line no-restricted-syntax -- Finding spans by CSS class within button
        const spans = b.querySelectorAll('span.font-medium')
        return [...spans].some((span) => span.textContent?.trim() === text)
      })
    }

    if (!button) {
      throw new Error(`Dialog button with exact text "${text}" not found`)
    }
    return button
  }

  /**
   * Waits for the router to navigate to a path matching the given pattern.
   * @param pathPattern - Regular expression to match against the current route path
   */
  async waitForRoute(pathPattern: RegExp): Promise<void> {
    await expectPoll(() => this.context.router.currentRoute.value.path).toMatch(pathPattern)
  }

  /**
   * Navigates to the exercises page by clicking the exercises nav button.
   * Waits for the route to update before returning.
   */
  async navigateToExercises(): Promise<void> {
    await page.getByRole('button', { name: /^exercises$/i }).click()
    await this.waitForRoute(/^\/exercises$/)
  }

  /**
   * Navigates to the settings page by clicking the settings nav button.
   * Waits for the route to update before returning.
   */
  async navigateToSettings(): Promise<void> {
    await page.getByRole('button', { name: /settings/i }).click()
    await this.waitForRoute(/^\/settings$/)
  }

  /**
   * Navigates to the workouts page by clicking the workouts nav button.
   * Waits for the route to update before returning.
   */
  async navigateToWorkouts(): Promise<void> {
    await page.getByRole('button', { name: /workouts/i }).click()
    await this.waitForRoute(/^\/workouts$/)
  }

  /**
   * Navigates to the workouts page and clicks a specific tab.
   * @param tabName - Tab name to click (e.g., 'templates', 'history')
   */
  async navigateToWorkoutsAndClickTab(tabName: string): Promise<void> {
    await this.navigateToWorkouts()
    const tabLocator = page.getByRole('tab', { name: new RegExp(tabName, 'i') })
    await expectElement(tabLocator).toBeVisible()
    await tabLocator.click()
  }

  /**
   * Sets the value of an input element directly and dispatches events.
   * Works around NumberField input quirks in browser mode.
   * @param input - The input element (from getByRole or similar query)
   * @param value - The value to set
   */
  private setInputValueDirectly(input: Element, value: string): void {
    if (!(input instanceof HTMLInputElement)) {
      throw new TypeError('Expected HTMLInputElement')
    }
    input.focus()
    // Use native setter to trigger React/Vue internals properly
    const nativeInputValueSetter = Object.getOwnPropertyDescriptor(
      globalThis.HTMLInputElement.prototype,
      'value',
    )?.set
    const setterFunction = nativeInputValueSetter ?? ((v: string) => { input.value = v })
    setterFunction.call(input, value)
    // Dispatch input and change events to trigger Vue reactivity
    input.dispatchEvent(new InputEvent('input', { bubbles: true, inputType: 'insertText' }))
    input.dispatchEvent(new Event('change', { bubbles: true }))
    input.blur()
  }

  /**
   * Fills strength set inputs (weight, reps, rir) and waits for button to be enabled.
   * Uses direct DOM manipulation to work around NumberField input quirks.
   * @param inputs - Object with weight, reps, rir input elements
   * @param values - Object with weight, reps, rir values as strings
   * @param completeButton - The Complete Set button element to wait for
   */
  async fillStrengthSetAndWaitForButton(
    inputs: { weight: Element; reps: Element; rir: Element },
    values: { weight: string; reps: string; rir: string },
    completeButton: Element,
  ): Promise<void> {
    this.setInputValueDirectly(inputs.weight, values.weight)
    this.setInputValueDirectly(inputs.reps, values.reps)
    this.setInputValueDirectly(inputs.rir, values.rir)
    await flushPromises()
    await expectPoll(() => !completeButton.hasAttribute('disabled')).toBe(true)
  }
}

/**
 * Happy-DOM Locator Implementation
 *
 * This module provides the Happy-DOM implementation of the Locator abstraction.
 * It uses @testing-library/vue for queries and @testing-library/user-event for interactions.
 *
 * Usage:
 * - Import `page` from this module instead of `vitest/browser`
 * - All queries and interactions work identically to the browser API
 *
 * Note: This file uses querySelectorAll for scoped element queries within locators.
 * This is intentional - testing-library's screen queries are only used at the page level.
 */

/* eslint-disable no-restricted-syntax */

import { screen } from '@testing-library/vue'
import testingLibraryUserEvent from '@testing-library/user-event'
import type {
  Locator,
  Page,
  ARIARole,
  LocatorOptions,
  LocatorByRoleOptions,
  UserEventClickOptions,
  UserEventFillOptions,
  UserEventClearOptions,
  UserEventHoverOptions,
  UserEventSelectOptions,
} from './types'

// Create a userEvent instance for all interactions
const user = testingLibraryUserEvent.setup()


/**
 * Type guard to check if a value is a HappyDomLocator
 */
function isHappyDomLocator(value: unknown): value is HappyDomLocator {
  return value instanceof HappyDomLocator
}

/**
 * Type guard to check if a value is an HTMLElement
 */
function isHTMLElement(value: unknown): value is HTMLElement {
  return value instanceof HTMLElement
}

/**
 * Type guard to check if a value is an HTMLSelectElement
 */
function isHTMLSelectElement(value: unknown): value is HTMLSelectElement {
  return value instanceof HTMLSelectElement
}

/**
 * Type guard to check if a value is a string
 */
function isString(value: unknown): value is string {
  return typeof value === 'string'
}

/**
 * Convert LocatorByRoleOptions to testing-library format
 * Note: testing-library's getByRole doesn't support 'exact' option
 */
function toByRoleOptions(options?: LocatorByRoleOptions): Parameters<typeof screen.getByRole>[1] {
  if (!options) {
    return undefined
  }
  return {
    checked: options.checked,
    pressed: options.pressed,
    selected: options.selected,
    expanded: options.expanded,
    level: options.level,
    hidden: options.includeHidden,
    name: options.name,
  }
}

/**
 * Convert LocatorOptions to testing-library format
 */
function toQueryOptions(options?: LocatorOptions): { exact?: boolean } | undefined {
  if (!options) {
    return undefined
  }
  return {
    exact: options.exact,
  }
}

/**
 * Check if text matches a string or regex pattern
 */
function textMatches(text: string, pattern: string | RegExp, exact?: boolean): boolean {
  if (typeof pattern === 'string') {
    return exact ? text === pattern : text.includes(pattern)
  }
  return pattern.test(text)
}

/**
 * Filter elements based on hasText/hasNotText options
 */
function filterByText(elements: Array<HTMLElement>, options?: LocatorOptions): Array<HTMLElement> {
  if (!options) {
    return elements
  }

  return elements.filter((el) => {
    const text = el.textContent ?? ''

    if (options.hasText && !textMatches(text, options.hasText)) {
      return false
    }

    if (options.hasNotText && textMatches(text, options.hasNotText)) {
      return false
    }

    return true
  })
}

/**
 * Filter elements based on has/hasNot locator options
 */
function filterByLocator(elements: Array<HTMLElement>, options?: LocatorOptions): Array<HTMLElement> {
  if (!options) {
    return elements
  }

  return elements.filter((el) => {
    if (options.has && isHappyDomLocator(options.has)) {
      // Element must contain a match for the 'has' locator
      const hasMatch = options.has.queryWithin(el)
      if (!hasMatch) return false
    }

    if (options.hasNot && isHappyDomLocator(options.hasNot)) {
      // Element must NOT contain a match for the 'hasNot' locator
      const hasNotMatch = options.hasNot.queryWithin(el)
      if (hasNotMatch) return false
    }

    return true
  })
}

/**
 * Apply all filters to elements
 */
function applyFilters(elements: Array<HTMLElement>, options?: LocatorOptions): Array<HTMLElement> {
  let result = elements
  result = filterByText(result, options)
  result = filterByLocator(result, options)
  return result
}

/**
 * Safely cast array of Elements to HTMLElement array using filter
 */
function toHTMLElements(elements: Array<Element>): Array<HTMLElement> {
  return elements.filter(isHTMLElement)
}

/**
 * Extract HTMLElement from a locator's element() result
 */
function getHTMLElementFromLocator(locator: HappyDomLocator): HTMLElement {
  const el = locator.element()
  if (!isHTMLElement(el)) {
    throw new Error('Expected HTMLElement from locator')
  }
  return el
}

/**
 * Convert select values to user-event format
 */
function convertSelectValues(
  values: HTMLElement | HTMLElement[] | Locator | Locator[] | string | string[],
): HTMLElement | HTMLElement[] | string | string[] {
  // Handle single Locator
  if (isHappyDomLocator(values)) {
    return getHTMLElementFromLocator(values)
  }

  // Handle single HTMLElement
  if (isHTMLElement(values)) {
    return values
  }

  // Handle string
  if (isString(values)) {
    return values
  }

  // Handle arrays - need to process each element
  if (!Array.isArray(values)) {
    // This shouldn't happen given the type, but TypeScript needs it
    throw new TypeError('Unexpected value type for selectOptions')
  }

  return convertArrayValues(values)
}

/**
 * Convert array of select values
 */
function convertArrayValues(
  values: Array<HTMLElement | Locator | string>,
): HTMLElement[] | string[] {
  const firstValue = values[0]
  if (firstValue === undefined) {
    return []
  }

  // Check if array contains locators
  if (isHappyDomLocator(firstValue)) {
    return extractLocatorElements(values)
  }

  // Check if array contains HTMLElements
  if (isHTMLElement(firstValue)) {
    return extractHTMLElements(values)
  }

  // Must be strings
  if (isString(firstValue)) {
    return extractStrings(values)
  }

  throw new Error('Unexpected array element type for selectOptions')
}

function extractLocatorElements(values: Array<HTMLElement | Locator | string>): Array<HTMLElement> {
  const result: Array<HTMLElement> = []
  for (const v of values) {
    if (isHappyDomLocator(v)) {
      result.push(getHTMLElementFromLocator(v))
    }
  }
  return result
}

function extractHTMLElements(values: Array<HTMLElement | Locator | string>): Array<HTMLElement> {
  const result: Array<HTMLElement> = []
  for (const v of values) {
    if (isHTMLElement(v)) {
      result.push(v)
    }
  }
  return result
}

function extractStrings(values: Array<HTMLElement | Locator | string>): Array<string> {
  const result: Array<string> = []
  for (const v of values) {
    if (isString(v)) {
      result.push(v)
    }
  }
  return result
}

/**
 * Mapping of ARIA roles to their implicit HTML element selectors.
 * HTML elements have implicit ARIA roles that don't require explicit role attributes.
 * @see https://www.w3.org/TR/html-aria/#docconformance
 */
const IMPLICIT_ROLE_SELECTORS: Record<string, string> = {
  // Table roles
  table: 'table',
  row: 'tr',
  cell: 'td',
  columnheader: 'th',
  rowheader: 'th[scope="row"]',
  rowgroup: 'tbody, thead, tfoot',
  // Form roles
  button: 'button, input[type="button"], input[type="submit"], input[type="reset"], input[type="image"]',
  checkbox: 'input[type="checkbox"]',
  radio: 'input[type="radio"]',
  textbox: 'input:not([type]), input[type="text"], input[type="email"], input[type="tel"], input[type="url"], input[type="search"], input[type="password"], textarea',
  spinbutton: 'input[type="number"]',
  combobox: 'select:not([multiple]):not([size]), select[size="1"]',
  listbox: 'select[multiple], select[size]:not([size="1"])',
  slider: 'input[type="range"]',
  option: 'option',
  // Landmark roles
  main: 'main',
  navigation: 'nav',
  banner: 'header:not(article header, section header)',
  contentinfo: 'footer:not(article footer, section footer)',
  complementary: 'aside',
  form: 'form[aria-label], form[aria-labelledby], form[name]',
  region: 'section[aria-label], section[aria-labelledby]',
  search: 'search',
  // Document structure roles
  article: 'article',
  heading: 'h1, h2, h3, h4, h5, h6',
  list: 'ul, ol',
  listitem: 'li',
  link: 'a[href]',
  img: 'img[alt]:not([alt=""])',
  figure: 'figure',
  separator: 'hr',
  // Widget roles
  dialog: '[role="dialog"], dialog',
  tab: '[role="tab"]',
  tablist: '[role="tablist"]',
  tabpanel: '[role="tabpanel"]',
  menu: '[role="menu"]',
  menuitem: '[role="menuitem"]',
  menuitemcheckbox: '[role="menuitemcheckbox"]',
  menuitemradio: '[role="menuitemradio"]',
  progressbar: 'progress',
  status: 'output',
  alert: '[role="alert"]',
  alertdialog: '[role="alertdialog"]',
  tooltip: '[role="tooltip"]',
  tree: '[role="tree"]',
  treeitem: '[role="treeitem"]',
  grid: '[role="grid"]',
  gridcell: '[role="gridcell"]',
}

/**
 * Build a CSS selector for a given ARIA role that includes both explicit and implicit matches.
 */
function buildRoleSelector(role: string): string {
  const explicitSelector = `[role="${role}"]`
  const implicitSelector = IMPLICIT_ROLE_SELECTORS[role]

  if (implicitSelector) {
    return `${explicitSelector}, ${implicitSelector}`
  }
  return explicitSelector
}

/**
 * Get the accessible name from aria-labelledby attribute.
 */
function getNameFromLabelledBy(element: HTMLElement): string | null {
  const labelledBy = element.getAttribute('aria-labelledby')
  if (!labelledBy) return null

  const labelIds = labelledBy.split(/\s+/)
  const labelTexts: Array<string> = []
  for (const id of labelIds) {
    const labelElement = document.querySelector(`#${id}`)
    if (labelElement) {
      labelTexts.push(labelElement.textContent?.trim() ?? '')
    }
  }
  const combinedLabel = labelTexts.join(' ').trim()
  return combinedLabel || null
}

/**
 * Get the accessible name from associated label element.
 */
function getNameFromAssociatedLabel(element: HTMLElement): string | null {
  if (!(element instanceof HTMLInputElement || element instanceof HTMLTextAreaElement || element instanceof HTMLSelectElement)) {
    return null
  }
  const { id } = element
  if (!id) return null

  const label = document.querySelector<HTMLLabelElement>(`label[for="${id}"]`)
  return label?.textContent?.trim() ?? null
}

/**
 * Get the accessible name of an element.
 * Checks aria-label, aria-labelledby, and falls back to text content.
 * @see https://www.w3.org/TR/accname-1.1/
 */
function getAccessibleName(element: HTMLElement): string {
  // 1. Check aria-label attribute
  const ariaLabel = element.getAttribute('aria-label')
  if (ariaLabel) return ariaLabel.trim()

  // 2. Check aria-labelledby attribute
  const labelledByName = getNameFromLabelledBy(element)
  if (labelledByName) return labelledByName

  // 3. For form elements, check associated label
  const associatedLabel = getNameFromAssociatedLabel(element)
  if (associatedLabel) return associatedLabel

  // 4. Fall back to text content for buttons, links, etc.
  return element.textContent?.trim() ?? ''
}

/**
 * Filter elements by accessible name.
 */
function filterByAccessibleName(elements: Array<HTMLElement>, namePattern: string | RegExp | undefined): Array<HTMLElement> {
  if (namePattern === undefined) {
    return elements
  }

  return elements.filter((el) => {
    const accessibleName = getAccessibleName(el)
    return textMatches(accessibleName, namePattern)
  })
}

/**
 * Filter out elements that have an explicit role attribute different from the target role.
 * This ensures that implicit role matching (e.g., input[type="text"] matching "textbox")
 * doesn't match elements with an explicit role override (e.g., role="spinbutton").
 */
function filterByExplicitRole(elements: Array<HTMLElement>, targetRole: string): Array<HTMLElement> {
  return elements.filter((el) => {
    const explicitRole = el.getAttribute('role')
    // If no explicit role, the implicit role applies - keep the element
    if (!explicitRole) return true
    // If explicit role matches target, keep it
    if (explicitRole === targetRole) return true
    // Explicit role differs from target - exclude this element
    return false
  })
}

/**
 * Create a scoped query function for getByRole within parent elements
 */
function createScopedRoleQuery(
  parentQueryFn: () => Array<HTMLElement>,
  role: ARIARole | (string & {}),
  options?: LocatorByRoleOptions,
): () => Array<HTMLElement> {
  return () => {
    const parentElements = parentQueryFn()
    const results: Array<HTMLElement> = []
    const selector = buildRoleSelector(role)
    for (const parentEl of parentElements) {
      const els = parentEl.querySelectorAll<HTMLElement>(selector)
      for (const el of els) {
        results.push(el)
      }
    }
    // Filter out elements with explicit roles that differ from the target role
    const filteredByExplicitRole = filterByExplicitRole(results, role)
    // Filter by accessible name if provided
    const filteredByName = filterByAccessibleName(filteredByExplicitRole, options?.name)
    return applyFilters(filteredByName, options)
  }
}

/**
 * Create a scoped query function for getByLabelText within parent elements
 */
function createScopedLabelTextQuery(
  parentQueryFn: () => Array<HTMLElement>,
  text: string | RegExp,
  options?: LocatorOptions,
): () => Array<HTMLElement> {
  return () => {
    const parentElements = parentQueryFn()
    const results: Array<HTMLElement> = []
    for (const parentEl of parentElements) {
      const labels = parentEl.querySelectorAll<HTMLLabelElement>('label')
      for (const label of labels) {
        const labelText = label.textContent ?? ''
        const matches = textMatches(labelText, text, options?.exact)
        if (matches && label.htmlFor) {
          const input = parentEl.querySelector<HTMLElement>(`#${label.htmlFor}`)
          if (input) results.push(input)
        }
      }
    }
    return applyFilters(results, options)
  }
}

/**
 * Create a scoped query function for getByAltText within parent elements
 */
function createScopedAltTextQuery(
  parentQueryFn: () => Array<HTMLElement>,
  text: string | RegExp,
  options?: LocatorOptions,
): () => Array<HTMLElement> {
  return () => {
    const parentElements = parentQueryFn()
    const results: Array<HTMLElement> = []
    for (const parentEl of parentElements) {
      const els = parentEl.querySelectorAll<HTMLElement>('[alt]')
      for (const el of els) {
        const altText = el.getAttribute('alt') ?? ''
        const matches = textMatches(altText, text, options?.exact)
        if (matches) results.push(el)
      }
    }
    return applyFilters(results, options)
  }
}

/**
 * Create a scoped query function for getByPlaceholder within parent elements
 */
function createScopedPlaceholderQuery(
  parentQueryFn: () => Array<HTMLElement>,
  text: string | RegExp,
  options?: LocatorOptions,
): () => Array<HTMLElement> {
  return () => {
    const parentElements = parentQueryFn()
    const results: Array<HTMLElement> = []
    for (const parentEl of parentElements) {
      const els = parentEl.querySelectorAll<HTMLElement>('[placeholder]')
      for (const el of els) {
        const placeholderText = el.getAttribute('placeholder') ?? ''
        const matches = textMatches(placeholderText, text, options?.exact)
        if (matches) results.push(el)
      }
    }
    return applyFilters(results, options)
  }
}

/**
 * Create a scoped query function for getByText within parent elements
 */
function createScopedTextQuery(
  parentQueryFn: () => Array<HTMLElement>,
  text: string | RegExp,
  options?: LocatorOptions,
): () => Array<HTMLElement> {
  return () => {
    const parentElements = parentQueryFn()
    const results: Array<HTMLElement> = []
    for (const parentEl of parentElements) {
      const walker = document.createTreeWalker(parentEl, NodeFilter.SHOW_TEXT)
      let node: Node | null
      while ((node = walker.nextNode())) {
        const nodeText = node.textContent ?? ''
        const textToMatch = options?.exact ? nodeText.trim() : nodeText
        const matches = textMatches(textToMatch, text, options?.exact)
        if (matches && node.parentElement) {
          results.push(node.parentElement)
        }
      }
    }
    return applyFilters(results, options)
  }
}

/**
 * Create a scoped query function for getByTitle within parent elements
 */
function createScopedTitleQuery(
  parentQueryFn: () => Array<HTMLElement>,
  text: string | RegExp,
  options?: LocatorOptions,
): () => Array<HTMLElement> {
  return () => {
    const parentElements = parentQueryFn()
    const results: Array<HTMLElement> = []
    for (const parentEl of parentElements) {
      const els = parentEl.querySelectorAll<HTMLElement>('[title]')
      for (const el of els) {
        const titleText = el.getAttribute('title') ?? ''
        const matches = textMatches(titleText, text, options?.exact)
        if (matches) results.push(el)
      }
    }
    return applyFilters(results, options)
  }
}

/**
 * Create a scoped query function for getByTestId within parent elements
 */
function createScopedTestIdQuery(
  parentQueryFn: () => Array<HTMLElement>,
  testId: string | RegExp,
): () => Array<HTMLElement> {
  return () => {
    const parentElements = parentQueryFn()
    const results: Array<HTMLElement> = []
    for (const parentEl of parentElements) {
      const els = parentEl.querySelectorAll<HTMLElement>('[data-testid]')
      for (const el of els) {
        const id = el.dataset.testid ?? ''
        const matches = typeof testId === 'string' ? id === testId : testId.test(id)
        if (matches) results.push(el)
      }
    }
    return results
  }
}

/**
 * Create an nth query function
 */
function createNthQuery(parentQueryFn: () => Array<HTMLElement>, index: number): () => Array<HTMLElement> {
  return () => {
    const elements = parentQueryFn()
    return elements[index] ? [elements[index]] : []
  }
}

/**
 * Create a last query function
 */
function createLastQuery(parentQueryFn: () => Array<HTMLElement>): () => Array<HTMLElement> {
  return () => {
    const elements = parentQueryFn()
    return elements.length > 0 ? [elements.at(-1)!] : []
  }
}

/**
 * Create an 'and' query function
 */
function createAndQuery(
  queryFn1: () => Array<HTMLElement>,
  queryFn2: () => Array<HTMLElement>,
): () => Array<HTMLElement> {
  return () => {
    const thisElements = new Set(queryFn1())
    const otherElements = queryFn2()
    return otherElements.filter((el) => thisElements.has(el))
  }
}

/**
 * Create an 'or' query function
 */
function createOrQuery(
  queryFn1: () => Array<HTMLElement>,
  queryFn2: () => Array<HTMLElement>,
): () => Array<HTMLElement> {
  return () => {
    const thisElements = queryFn1()
    const otherElements = queryFn2()
    const combined = new Map<HTMLElement, true>()
    for (const el of thisElements) combined.set(el, true)
    for (const el of otherElements) combined.set(el, true)
    return [...combined.keys()]
  }
}

/**
 * Create a filter query function
 */
function createFilterQuery(
  parentQueryFn: () => Array<HTMLElement>,
  options: LocatorOptions,
): () => Array<HTMLElement> {
  return () => {
    const elements = parentQueryFn()
    return applyFilters(elements, options)
  }
}

/**
 * Happy-DOM implementation of the Locator interface.
 * Uses @testing-library for queries and user-event for interactions.
 */
class HappyDomLocator implements Locator {
  private readonly queryFn: () => Array<HTMLElement>
  private readonly selectorStr: string

  constructor(queryFn: () => Array<HTMLElement>, selector: string) {
    this.queryFn = queryFn
    this.selectorStr = selector
  }

  get selector(): string {
    return this.selectorStr
  }

  /**
   * Query for elements within a specific container (used by has/hasNot)
   */
  queryWithin(container: HTMLElement): HTMLElement | null {
    const allElements = this.queryFn()
    return allElements.find((el) => container.contains(el)) ?? null
  }

  // ─── Query Methods ──────────────────────────────────────────────────────────

  getByRole(role: ARIARole | (string & {}), options?: LocatorByRoleOptions): Locator {
    return new HappyDomLocator(
      createScopedRoleQuery(this.queryFn, role, options),
      `${this.selectorStr} >> role=${role}`,
    )
  }

  getByLabelText(text: string | RegExp, options?: LocatorOptions): Locator {
    return new HappyDomLocator(
      createScopedLabelTextQuery(this.queryFn, text, options),
      `${this.selectorStr} >> labelText=${String(text)}`,
    )
  }

  getByAltText(text: string | RegExp, options?: LocatorOptions): Locator {
    return new HappyDomLocator(
      createScopedAltTextQuery(this.queryFn, text, options),
      `${this.selectorStr} >> altText=${String(text)}`,
    )
  }

  getByPlaceholder(text: string | RegExp, options?: LocatorOptions): Locator {
    return new HappyDomLocator(
      createScopedPlaceholderQuery(this.queryFn, text, options),
      `${this.selectorStr} >> placeholder=${String(text)}`,
    )
  }

  getByText(text: string | RegExp, options?: LocatorOptions): Locator {
    return new HappyDomLocator(
      createScopedTextQuery(this.queryFn, text, options),
      `${this.selectorStr} >> text=${String(text)}`,
    )
  }

  getByTitle(text: string | RegExp, options?: LocatorOptions): Locator {
    return new HappyDomLocator(
      createScopedTitleQuery(this.queryFn, text, options),
      `${this.selectorStr} >> title=${String(text)}`,
    )
  }

  getByTestId(testId: string | RegExp): Locator {
    return new HappyDomLocator(
      createScopedTestIdQuery(this.queryFn, testId),
      `${this.selectorStr} >> testId=${String(testId)}`,
    )
  }

  // ─── Interaction Methods ────────────────────────────────────────────────────

  async click(_options?: UserEventClickOptions): Promise<void> {
    const el = this.element()
    await user.click(el)
  }

  async dblClick(_options?: UserEventClickOptions): Promise<void> {
    const el = this.element()
    await user.dblClick(el)
  }

  async fill(text: string, _options?: UserEventFillOptions): Promise<void> {
    const el = this.element()
    await user.clear(el)
    // user.type() doesn't accept empty strings
    if (text) {
      await user.type(el, text)
    }
  }

  async clear(_options?: UserEventClearOptions): Promise<void> {
    const el = this.element()
    await user.clear(el)
  }

  async hover(_options?: UserEventHoverOptions): Promise<void> {
    const el = this.element()
    await user.hover(el)
  }

  async selectOptions(
    values: HTMLElement | HTMLElement[] | Locator | Locator[] | string | string[],
    _options?: UserEventSelectOptions,
  ): Promise<void> {
    const el = this.element()
    if (!isHTMLSelectElement(el)) {
      throw new Error('selectOptions can only be called on a <select> element')
    }

    const selectValues = convertSelectValues(values)
    await user.selectOptions(el, selectValues)
  }

  // ─── Element Access ─────────────────────────────────────────────────────────

  element(): HTMLElement | SVGElement {
    const elements = this.queryFn()
    if (elements.length === 0) {
      throw new Error(`No element found for selector: ${this.selectorStr}`)
    }
    if (elements.length > 1) {
      throw new Error(
        `Multiple elements (${elements.length}) found for selector: ${this.selectorStr}. Use nth(), first(), last(), or a more specific query.`,
      )
    }
    return elements[0]!
  }

  elements(): Array<HTMLElement | SVGElement> {
    return this.queryFn()
  }

  query(): HTMLElement | SVGElement | null {
    const elements = this.queryFn()
    if (elements.length === 0) {
      return null
    }
    if (elements.length > 1) {
      throw new Error(
        `Multiple elements (${elements.length}) found for selector: ${this.selectorStr}. Use nth(), first(), last(), or a more specific query.`,
      )
    }
    return elements[0]!
  }

  // ─── Collection Methods ─────────────────────────────────────────────────────

  all(): Array<Locator> {
    const elements = this.queryFn()
    const queryFnRef = this.queryFn
    const selectorBase = this.selectorStr
    return elements.map(
      (_el, index) =>
        new HappyDomLocator(
          createNthQuery(queryFnRef, index),
          `${selectorBase} >> nth=${index}`,
        ),
    )
  }

  nth(index: number): Locator {
    return new HappyDomLocator(
      createNthQuery(this.queryFn, index),
      `${this.selectorStr} >> nth=${index}`,
    )
  }

  first(): Locator {
    return this.nth(0)
  }

  last(): Locator {
    return new HappyDomLocator(
      createLastQuery(this.queryFn),
      `${this.selectorStr} >> last`,
    )
  }

  // ─── Chaining Methods ───────────────────────────────────────────────────────

  and(locator: Locator): Locator {
    if (!isHappyDomLocator(locator)) {
      throw new Error('and() requires a HappyDomLocator instance')
    }
    return new HappyDomLocator(
      createAndQuery(this.queryFn, locator.queryFn),
      `(${this.selectorStr}) AND (${locator.selector})`,
    )
  }

  or(locator: Locator): Locator {
    if (!isHappyDomLocator(locator)) {
      throw new Error('or() requires a HappyDomLocator instance')
    }
    return new HappyDomLocator(
      createOrQuery(this.queryFn, locator.queryFn),
      `(${this.selectorStr}) OR (${locator.selector})`,
    )
  }

  filter(options: LocatorOptions): Locator {
    return new HappyDomLocator(
      createFilterQuery(this.queryFn, options),
      `${this.selectorStr} >> filter`,
    )
  }
}

